KINDS = ("rules", "extraction", "site", "summary", "translation", "summary_translation")


def text(kind, lang="en", model=None):
    """The disclosure sentence(s) for `kind` in `lang`; `model` names the AI model when one wrote the text."""
    if kind not in KINDS:
        raise ValueError(f"unknown disclosure kind {kind!r}")
    body = _TEXT[lang][kind]
    if "{model}" in body:
        if not model:
            raise ValueError(f"disclosure kind {kind!r} needs the model name")
        body = body.replace("{model}", model)
    return body


def markdown(kind, lang="en", model=None):
    """A one-paragraph Markdown blockquote with the disclosure and a link to AI.md."""
    t = _TEXT[lang]
    return f"> **{t['heading']}** {text(kind, lang, model)} [{t['more']}]({AI_PAGE_URL})"


def html(kind, lang="en", model=None):
    """The same notice as an HTML paragraph (already escaped)."""
    import html as _html
    t = _TEXT[lang]
    return (f'<p class="ai"><strong>{_html.escape(t["heading"])}</strong> {_html.escape(text(kind, lang, model))} '
            f'<a href="{AI_PAGE_URL}">{_html.escape(t["more"])}</a></p>')


def produced_by(kind, model=None):
    return {"rules": "software (programmed rules) written with AI assistance",
            "site": "software and documents written with AI assistance",
            "extraction": "software (extraction and OCR) written with AI assistance",
            "summary": f"AI model ({model})", "translation": f"AI model ({model})",
            "summary_translation": f"AI model ({model})"}[kind]


def front_matter(kind, model=None):
    """Machine-readable fields for a Markdown file's front matter."""
    return {"produced_by": f'"{produced_by(kind, model)}"', "human_reviewed": "false", "ai_disclosure": AI_PAGE_URL}


def labels(kind, model=None):
    """The same, for a JSON file's `labels` object."""
    return {"produced_by": produced_by(kind, model), "human_reviewed": False, "ai_disclosure": AI_PAGE_URL,
            "disclaimer": text(kind, "en", model)}


def with_front_matter(body, title, kind="rules", model=None):
    """Prefix a generated Markdown page with machine-readable front matter (the visible notice is in `body`)."""
    lines = ["---", f'title: "{title}"', "machine_generated: true"]
    lines += [f"{k}: {v}" for k, v in front_matter(kind, model).items()]
    return "\n".join(lines + ["---", ""]) + body

